import random
def parse(stdin):
    t = list(map(int, stdin.split()))
    assert len(t) >= 2 and len(t) == 2 + 2 * t[0]
    return {'W': t[1], 'items': [[t[2 + 2 * i], t[3 + 2 * i]] for i in range(t[0])]}
def render(case):
    lines = [f"{len(case['items'])} {case['W']}"]
    lines.extend(f"{w} {v}" for w, v in case['items'])
    return chr(10).join(lines)
def valid(case):
    if not isinstance(case, dict) or 'W' not in case or 'items' not in case:
        return False
    W, it = case['W'], case['items']
    return (isinstance(W, int) and 1 <= W <= 20 and isinstance(it, list) and 1 <= len(it) <= 8 and
            all(isinstance(x, list) and len(x) == 2 and isinstance(x[0], int) and 1 <= x[0] <= 10 and
                isinstance(x[1], int) and 1 <= x[1] <= 20 for x in it))
def solve(stdin):
    c = parse(stdin)
    W, it = c['W'], c['items']
    best = 0
    for m in range(1 << len(it)):
        sw = sum(it[i][0] for i in range(len(it)) if (m >> i) & 1)
        if sw <= W:
            sv = sum(it[i][1] for i in range(len(it)) if (m >> i) & 1)
            if sv > best: best = sv
    return str(best)
def generate(seed, index, mode):
    if mode == 'exhaustive':
        if index >= 32: return None
        n = 1 + (index & 1)
        w = 1 + ((index >> 1) % 4)
        it = [[1 + (i % 2), 1 + ((index >> (3 + i)) % 2)] for i in range(n)]
        return {'W': w, 'items': it}
    if mode == 'random':
        rng = random.Random(seed + index)
        n, W = rng.randint(1, 8), rng.randint(1, 20)
        return {'W': W, 'items': [[rng.randint(1, 10), rng.randint(1, 20)] for _ in range(n)]}
    adv = [{'W': 1, 'items': [[10, 20]]}, {'W': 20, 'items': [[1, 20]] * 8}, {'W': 5, 'items': [[6, 10]]}]
    return adv[index % len(adv)]
def shrink(case):
    out, it, W = [], case['items'], case['W']
    if len(it) > 1:
        out.append({'W': W, 'items': it[:-1]})
        out.append({'W': W, 'items': it[1:]})
    if W > 1:
        out.append({'W': max(1, W // 2), 'items': it})
    for i in range(min(2, len(it))):
        w, v = it[i]
        if w > 1 or v > 1:
            mod = [row[:] for row in it]
            mod[i] = [max(1, w // 2), max(1, v // 2)]
            out.append({'W': W, 'items': mod})
    return [c for c in out if valid(c)][:16]

