def valid_input(stdin):
    t = stdin.split()
    if len(t) < 2:
        return False
    try:
        n, W = int(t[0]), int(t[1])
    except ValueError:
        return False
    if not (1 <= n <= 8 and 1 <= W <= 20):
        return False
    if len(t) != 2 + 2 * n:
        return False
    for i in range(n):
        try:
            w, v = int(t[2 + 2 * i]), int(t[3 + 2 * i])
        except ValueError:
            return False
        if not (1 <= w <= 10 and 1 <= v <= 20):
            return False
    return True

def solve(stdin):
    t = list(map(int, stdin.split()))
    n, W = t[0], t[1]
    items = [(t[2 + 2 * i], t[3 + 2 * i]) for i in range(n)]
    best = 0
    for mask in range(1 << n):
        tot_w = sum(items[i][0] for i in range(n) if (mask >> i) & 1)
        tot_v = sum(items[i][1] for i in range(n) if (mask >> i) & 1)
        if tot_w <= W and tot_v > best:
            best = tot_v
    return str(best)
